// A layered vector organ: crisp at stage resolution, with animated neural pathways.
// These regions are a storytelling metaphor, not anatomical localization claims.
export function winChatBrain({active=-1,mode='overview'}={}){
 const id=`wc-mind-${mode}`;
 const lobe='M394 117C370 75 310 76 285 112C245 102 208 133 213 174C169 188 154 236 181 268C168 306 204 343 242 339C261 381 308 389 337 356C367 371 394 344 394 309Z';
 const folds='M289 115C269 142 291 163 269 185S232 192 240 223S277 242 256 275S266 318 294 324 M351 117C319 147 337 171 311 194S291 230 316 246S336 278 314 298S320 329 336 355 M214 175C242 157 253 174 269 185 M182 267C208 249 232 252 256 275 M242 339C234 308 259 299 270 297 M394 182C361 169 339 197 359 220S376 252 354 271S354 313 393 309';
 const pair=(path,attrs='')=>`<path d="${path}" ${attrs}/><path d="${path}" transform="translate(800 0) scale(-1 1)" ${attrs}/>`;
 const points=[],regions=[{nodes:'',links:''},{nodes:'',links:''},{nodes:'',links:''}];
 for(let i=0;i<280;i++){
  const x=172+((i*137.508)%456),y=90+((i*83.317)%295),region=y>290?2:x<400?0:1;
  const current=regions[region];
  current.nodes+=`<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="${i%11===0?2.4:1.05}" style="--delay:${i%13*-.4}s"/>`;
  points.filter(p=>Math.hypot(p[0]-x,p[1]-y)<34).slice(-2).forEach(p=>current.links+=`<path d="M${p[0]} ${p[1]}L${x} ${y}"/>`);
  points.push([x,y]);
 }
 const labels=[['RAG','知識依據'],['SKILL','方法與工具'],['WORK','工作成果']];
 return `<div class="wc-mind-scene" data-active="${active}" data-mode="${mode}"><div class="wc-mind-aura"></div><svg class="wc-mind-organ" viewBox="80 30 650 440" role="img" aria-label="Agent 結合 RAG 知識與 SKILL 工作能力，產出工作成果的企業大腦"><defs><radialGradient id="${id}-surface" cx=".32" cy=".23" r=".85"><stop stop-color="#aa99ce" stop-opacity=".64"/><stop offset=".48" stop-color="#514664" stop-opacity=".78"/><stop offset="1" stop-color="#141e34" stop-opacity=".94"/></radialGradient><linearGradient id="${id}-rim" x2=".9" y2="1"><stop stop-color="#e1d8f5"/><stop offset=".45" stop-color="#968bb6"/><stop offset="1" stop-color="#38455e"/></linearGradient><radialGradient id="${id}-light"><stop stop-color="#e6d3ff" stop-opacity=".9"/><stop offset="1" stop-color="#b18ce0" stop-opacity="0"/></radialGradient><clipPath id="${id}-clip">${pair(lobe)}</clipPath></defs><g class="wc-mind-orbits"><ellipse cx="400" cy="250" rx="295" ry="82" transform="rotate(-22 400 250)"/><ellipse cx="400" cy="250" rx="289" ry="76" transform="rotate(25 400 250)"/></g><g class="wc-mind-volume">${[12,9,6,3].map((offset,i)=>`<g transform="translate(${offset*.4} ${offset})" fill="${['#111c30','#1b2339','#2c2944','#4b405f'][i]}" stroke="#a293bf24" stroke-width="1">${pair(lobe)}</g>`).join('')}<g fill="url(#${id}-surface)" stroke="url(#${id}-rim)" stroke-width="1.5">${pair(lobe)}</g><g class="wc-mind-fold-shadow">${pair(folds)}</g><g class="wc-mind-fold-light" transform="translate(-1 -2)">${pair(folds)}</g><g clip-path="url(#${id}-clip)">${regions.map((r,i)=>`<g class="wc-mind-region region-${i}" style="--region:${i};--cycle-delay:${i*2.3}s"><g class="wc-mind-links">${r.links}</g><g class="wc-mind-nodes">${r.nodes}</g><circle class="wc-region-wash" cx="${[280,520,400][i]}" cy="${[205,200,330][i]}" r="100" fill="url(#${id}-light)"/></g>`).join('')}<g class="wc-mind-impulses"><path d="M189 250Q240 190 290 210T391 175 M611 250Q560 190 510 210T409 175 M280 330Q400 240 520 330"/></g></g><path class="wc-mind-stem" d="M394 310V389Q400 420 406 389V310"/><circle class="wc-mind-center-halo" cx="400" cy="259" r="36" fill="url(#${id}-light)"/><circle class="wc-mind-center" cx="400" cy="259" r="4"/></g></svg>${mode==='overview'?`<div class="wc-brain-agent"><b>Agent</b><span>理解 · 規劃 · 調用 · 檢視</span></div><div class="wc-mind-labels">${labels.map((l,i)=>`<div class="mind-label-${i}"><i></i><b>${l[0]}</b><span>${l[1]}</span></div>`).join('')}</div>`:''}</div>`;
}
